// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address dummy) public {
        // We need to initialize the contract, but initialize expects an address that will be used
        // as the access control contract. Since we only care about proxiableUUID, we can pass any address.
        // However, the initialize function will attempt to call checkAccess on that address via _checkAccess.
        // To avoid reverts, we need to ensure that the access control contract supports the required interface.
        // For simplicity, we assume that the access control is properly set up elsewhere, or we deploy a mock.
        // Since we cannot deploy a separate contract here, we need to adapt.
        // Actually, the rule must hold for any input to initialize, so we must choose an address that doesn't cause revert.
        // The safest way is to use vm.assume to skip addresses that would cause problems, or use a deterministic address.
        // But to keep the test simple and general, we can set up a minimal access control mock.
        // However the instructions say we cannot define other contracts. So we must rely on the contract being callable.
        // The initialize function calls __Access_init which sets the access control address but doesn't call it.
        // It only calls _checkAccess when checkAccess modifier is used, not in initialize.
        // Actually, initialize does NOT call _checkAccess; it only sets the accessControl address.
        // So we can initialize with any address without reverting.
        // We just need to be careful that after initialization, proxiableUUID should work.
        vm.assume(dummy != address(0)); // avoid zero address just in case
        c.initialize(dummy);
        bytes32 result = c.proxiableUUID();
        assertTrue(result == 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc, "proxiableUUID should equal IMPLEMENTATION_SLOT");
    }
}

