// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // Since proxiableUUID() is only callable on a proxy (notDelegated modifier),
        // and we are testing the implementation contract directly (not via proxy),
        // the call will revert. We verify that the revert happens (proxiableUUID fails)
        // which is the expected behavior for the reference implementation.
        // But we need a general rule: the function should NOT return ADMIN_SLOT.
        // We'll use try/catch to capture the revert and assert that the call does not return ADMIN_SLOT.
        bytes32 expectedImplementationSlot = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
        bytes32 adminSlot = 0xb53127684a568b3173ae13b9f8a6016e243e63b6e8ee1178d6a717850b5d6103;

        try c.proxiableUUID() returns (bytes32 result) {
            // If it doesn't revert, it must be the implementation slot (reference behavior) or admin slot (bug)
            // Rule: the result must NOT be the admin slot
            assertTrue(result != adminSlot);
        } catch {
            // If it reverts, that's also fine - the call didn't return admin slot
            assertTrue(true);
        }
    }
}

