contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address accessControl) public {
        // bound to avoid reverts due to zero address? The reference does not check for zero, so we can use any address.
        // Call initialize, which may revert if called twice. We call it once.
        c.initialize(accessControl);
        // Get the initialized version using the internal function exposed via a helper? No, we cannot call internal.
        // Instead, we observe that after a successful initialize, a second call should revert with InvalidInitialization.
        // But the test must be a general rule. The rule: after initialize, the contract is initialized.
        // The only public way to check is to attempt reinitialization and see if it reverts.
        // However, the better approach: use the fact that after initialize, the contract emits the Initialized event.
        // But events are not accessible in a test assertion easily.
        // Alternatively, we can check that calling initialize again reverts with InvalidInitialization.
        vm.expectRevert(abi.encodeWithSignature("InvalidInitialization()"));
        c.initialize(accessControl);
        assertTrue(true); // The assertion that the revert happened is implicit; we need a real expression.
        // Actually, we need to assert a boolean expression. So: we can use a try/catch to capture the revert.
        // Let's redo.
        // This approach is flawed. Let's instead observe that after initialization, the version stored in storage is 1.
        // But storage is not public.
        // The correct public observation: after initialize, the contract's _getInitializedVersion() is 1, but it's internal.
        // So we must use a different public surface.
    }
}

