import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _admin) public {
        // Restrict to a valid address (non-zero to avoid issues, though not strictly required)
        vm.assume(_admin != address(0));

        // Call initialize; it reverts on double-initialization, but we catch that
        try c.initialize(_admin) {
            // success: no revert
        } catch {
            // revert: test should still check the rule below
        }

        // The rule: after any sequence of calls ending with initialize,
        // the getter for the private _getInitializedVersion() does not exist.
        // We must use the public/external view function that returns the initialized version.
        // However, C does not have such a public getter. The only public view function
        // that reveals the version is `proxiableUUID()` or similar? No.
        // Actually C inherits Initializable which has `_getInitializedVersion()` internal.
        // There is no public getter for the version. So the test must rely on a different public surface.
        // The only difference is that the event Initialized is emitted with version 2 in the mutant.
        // We can check for the event using vm.getRecordedLogs().

        // Clear any previous logs
        vm.recordLogs();

        // Call initialize again (will revert if already initialized, but we need a call that triggers the event)
        // Since the initializer modifier only emits when isTopLevelCall, and after the first call _initialized is 1,
        // the second call will revert in the initialSetup/construction check. So the event is only emitted once.
        // We can deploy a fresh C each time, but the test is fuzzed. We'll deploy fresh inside the fuzz.
        // Actually we can create a new C inside the fuzz to ensure fresh state.
        c = new C();

        vm.recordLogs();
        c.initialize(_admin);
        Vm.Log[] memory logs = vm.getRecordedLogs();

        // The event Initialized(uint64) has topic0 = keccak256("Initialized(uint64)")
        bytes32 expectedTopic = keccak256("Initialized(uint64)");
        bool foundInitializedEvent = false;
        uint64 emittedVersion;
        for (uint i = 0; i < logs.length; i++) {
            if (logs[i].topics.length > 0 && logs[i].topics[0] == expectedTopic) {
                foundInitializedEvent = true;
                // The version is the first topic? No, for event Initialized(uint64), the uint64 is non-indexed,
                // so it's in the data, not topics. The topics array has only the event signature.
                // The data is bytes, we need to decode it.
                // We can use abi.decode on logs[i].data to get uint64.
                emittedVersion = abi.decode(logs[i].data, (uint64));
                break;
            }
        }

        // The rule: the emitted version must be 1, not 2.
        assertTrue(foundInitializedEvent && emittedVersion == 1, "Initialized version should be 1");
    }
}

